import { readFileSync } from 'fs'
import { resolve } from 'path'
import { describe, expect, it } from 'vitest'
import { FEATURES, forecastFromParams, type FeatureRow, type ModelParams } from '../src/services/MoodForecast'

// The API's forecast must match the Python model's to the last decimal.
// Cases are generated by `python -m livora_ml.parity` (ml/).

type Case = { name: string; date: string; params: ModelParams; today: FeatureRow | null; yesterday: FeatureRow | null; expected: { mean: number; lower: number; upper: number } }
const { cases } = JSON.parse(readFileSync(resolve(__dirname, '../ml/tests/fixtures/forecast_parity.json'), 'utf8')) as { cases: Case[] }

describe('mood forecast matches the Python model', () => {
  it('has cases to check', () => {
    expect(cases.length).toBeGreaterThan(10)
  })

  it.each(cases.map((c) => [c.name, c] as const))('%s', (_name, c) => {
    const got = forecastFromParams(c.params, c.today, c.yesterday, c.date)
    expect(got).not.toBeNull()
    expect(got!.mean).toBeCloseTo(c.expected.mean, 10)
    expect(got!.lower).toBeCloseTo(c.expected.lower, 10)
    expect(got!.upper).toBeCloseTo(c.expected.upper, 10)
  })

  it('uses the same inputs, in the same order, as the saved model', () => {
    expect(cases[0].params.features).toEqual(FEATURES.map((f) => f.name))
  })

  it('refuses a model saved for different inputs', () => {
    const params = { ...cases[0].params, features: ['somethingElse', ...cases[0].params.features.slice(1)] }
    expect(forecastFromParams(params, null, null, cases[0].date)).toBeNull()
  })
})
